package android.widget;
public class ListPopupWindow { private final PopupWindow popup; private ListAdapter adapter; private ListView list; private final android.content.Context context; public ListPopupWindow(android.content.Context c) { context=c; popup=new PopupWindow(c); } public ListPopupWindow(android.content.Context c,android.util.AttributeSet a) { this(c); } public ListPopupWindow(android.content.Context c,android.util.AttributeSet a,int s) { this(c); } public ListPopupWindow(android.content.Context c,android.util.AttributeSet a,int s,int r) { this(c); } public void setAdapter(ListAdapter a) { adapter=a; if(list!=null) list.setAdapter(a); } public void setAnchorView(android.view.View v) {} public void setModal(boolean b) { popup.setFocusable(b); } public void setWidth(int w) { popup.setWidth(w); } public void setHeight(int h) { popup.setHeight(h); } public void setBackgroundDrawable(android.graphics.drawable.Drawable d) { popup.setBackgroundDrawable(d); } public void setOnDismissListener(PopupWindow.OnDismissListener l) { popup.setOnDismissListener(l); } public void show() { if(list==null) { list=new ListView(context); list.setAdapter(adapter); popup.setContentView(list); } popup.showAtLocation(list,0,0,0); } public void dismiss() { popup.dismiss(); } public boolean isShowing() { return popup.isShowing(); } public ListView getListView() { return list; } }
